import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {geometry,carbon,DEMO,FORMULA,SOURCE,validateRecord,parseRecords,summarize,latestRecords,csvCell} from '../../dist/school3d/tree/quest-core.js';
const near=(a,b)=>assert.ok(Math.abs(a-b)<1e-8,`${a} != ${b}`);
near(geometry({steps:8,length:1,eye:1.3}).height,9.3);
near(geometry({steps:8,length:.75,eye:1.3}).height,7.3);
const field={steps:8,length:1,eye:1.3,mode:'field',fixedHeight:9.3,aligned:true};
assert.equal(geometry(field).valid,true);
const moved=geometry({...field,steps:10});near(moved.height,9.3);assert.ok(moved.angle<45);assert.equal(moved.valid,false);
assert.equal(geometry({...field,level:false}).valid,false);
assert.equal(geometry({...field,aligned:false}).valid,false);
assert.equal(geometry({...field,calibrated:false}).valid,false);
assert.throws(()=>geometry({...field,steps:NaN}));
assert.throws(()=>geometry({...field,length:0}));
const input={circumference:Math.PI*30,height:10,group:'broadleaf'};
const result=carbon(input);near(result.dbhCm,30);near(result.dbhM,.3);near(result.volume,.31995);assert.equal(result.co2Kg,null);
near(carbon({...input,coefficients:DEMO}).co2Kg,.31995*.7*1.26*.47*44/12*1000);
assert.throws(()=>carbon({...input,group:'other'}));
assert.throws(()=>carbon({...input,coefficients:{...DEMO,source:''}}));
assert.throws(()=>carbon({...input,coefficients:{...DEMO,cf:2}}));
assert.throws(()=>carbon({...input,coefficients:{...DEMO,r:NaN}}));
const record={id:'example',name:'示範樹',species:'樟樹',date:'2026-10-29',circumference:120,height:9.3,group:'broadleaf',coefficients:DEMO,formulaId:FORMULA,sourceUrl:SOURCE,estimatedAt:'2026-10-29T00:00:00Z',measurementMethod:'demo_45_degree',measurement:{steps:8,length:1,eye:1.3,fixedHeight:9.3,level:true,aligned:false,calibrated:false},demo:true,platformId:null,location:null};
const valid=validateRecord(record),restored=parseRecords(JSON.stringify({version:1,records:[valid]}));
assert.deepEqual(restored,[valid]);
assert.throws(()=>parseRecords(JSON.stringify({version:2,records:[]})));
assert.throws(()=>parseRecords('null'),/第 1 版/);
assert.throws(()=>parseRecords('{bad'),/JSON 格式/);
assert.throws(()=>parseRecords(JSON.stringify({version:1,records:[record,record]})));
assert.throws(()=>validateRecord({...record,height:99}));
assert.throws(()=>validateRecord({...record,demo:false}));
const stats=summarize([{species:'樟樹',co2Kg:null},{species:'樟樹',co2Kg:100}]);
assert.equal(stats.total,100);assert.equal(stats.missing,1);assert.equal(stats.bySpecies[0].count,2);
assert.equal(summarize([{species:'缺值樹',co2Kg:null}]).total,null);
assert.equal(summarize([{species:'缺值樹',co2Kg:null}]).bySpecies[0].total,null);
assert.throws(()=>validateRecord({...record,date:'2026-02-31'}));
assert.throws(()=>validateRecord({...record,id:'bad" onclick="attack'}));
const original={...record,platformId:'MOE212344'},second={...original,id:'second',date:'2026-10-30'},fieldRecord={...original,id:'field',demo:false};
assert.deepEqual(latestRecords([original,second,fieldRecord],true),[second]);
assert.deepEqual(latestRecords([original,second,fieldRecord],false),[fieldRecord]);
near(geometry({...field,steps:8.1,aligned:true}).estimatedHeight,9.4);
assert.ok(csvCell('=HYPERLINK("bad")').startsWith('"\''));
const plants=JSON.parse(readFileSync(new URL('../../dist/school3d/tree/plants.json',import.meta.url),'utf8'));
assert.equal(plants.length,127);assert.equal(new Set(plants.map(p=>p.species)).size,46);
assert.equal(plants.filter(p=>p.sourceStockCO2e===null).length,3);
assert.ok(plants.every(p=>Number.isFinite(p.x)&&Number.isFinite(p.z)&&Number.isFinite(p.latitude)&&Number.isFinite(p.longitude)));
near(plants.reduce((sum,p)=>sum+(p.sourceStockCO2e??0),0),121456.56);
console.log('PASS: 45° geometry, fixed-height angle, ground restrictions, cm/m and t/kg conversions, missing coefficients, import provenance, statistics and CSV escaping.');
